const root='C:\\Users\\ADMIN\\Desktop\\chama1.0';
const schema=JSON.stringify({type:'object',properties:{id:{type:'string'},summary:{type:'string'},reviewed_paths:{type:'array',items:{type:'string'}},evidence:{type:'array',items:{type:'string'}},confirmed_source_gaps:{type:'array',items:{type:'string'}},suspected_issues:{type:'array',items:{type:'string'}},positive_controls:{type:'array',items:{type:'string'}},validation_blockers:{type:'array',items:{type:'string'}}},required:['id','summary','reviewed_paths','evidence','confirmed_source_gaps','suspected_issues','positive_controls','validation_blockers'],additionalProperties:false});
const areas=[
{id:'auth-api',brief:'Audit auth, sessions, authorization and API',prompt:'Read-only source audit for '+root+': authentication, PIN/session/recovery, roles, object authorization, CSRF/origin, input validation, API exposure, browser security and rate limits. Trace alternate paths and cite repository-relative path:line. Exclude every payment/M-Pesa route, callback, simulator and subscription-payment implementation. Do not read secrets, execute code/tests, use network, or write files. Separate source-confirmed gaps from suspected/deployment-dependent issues. Return JSON matching shared schema, id auth-api.'},
{id:'tenant-db',brief:'Audit tenant isolation and database constraints',prompt:'Read-only source audit for '+root+': multi-chama isolation, PostgreSQL RLS/context/runtime role, JSON state, repositories, active migrations, foreign keys, and current dirty/untracked tenant-integrity proposal/design/tests. Compare application controls to database invariants. Cite exact repo-relative path:line. Exclude payment/M-Pesa. No secrets, execution, network, or writes. Separate definite source gaps from actual exploitability that needs validation. Return shared schema id tenant-db.'},
{id:'cash-ledger',brief:'Audit cash ledger and double-entry consistency',prompt:'Read-only source audit for '+root+': ordinary in-app cash contributions and financial records, transaction/ledger entries, atomicity, idempotency, serialization, amount/date math, penalties/dividends, corrections/reversals, audit trail, and double-entry accounting. EXCLUDE M-Pesa, subscription payments, callbacks, simulator, and payment-provider code. Cite exact path:line. Distinguish absent accounting feature from security/integrity vulnerability. No execution, network, secret reads, or writes. Return shared schema id cash-ledger.'},
{id:'loans',brief:'Audit loans, guarantors and repayments',prompt:'Read-only source audit for '+root+': loan authorization/eligibility, guarantor checks and pledges, approval state machine, repayment arithmetic, duplicate/concurrent writes, idempotency, audit history, tenant scoping. Exclude provider/payment code. Cite exact path:line and report controls as well as gaps. No execution, network, secrets, or writes. Return shared schema id loans.'},
{id:'privacy-recovery',brief:'Audit privacy, exports and backup recovery',prompt:'Read-only source audit for '+root+': personal/financial data exposure, exports, local files/uploads, logs, retention/deletion, backup/restore and recovery integrity. Cite exact path:line; distinguish source behavior from unverified real backup/deployment processes. Exclude payment/M-Pesa. No secret reads, execution, network, or writes. Return shared schema id privacy-recovery.'},
{id:'production-ops',brief:'Audit deployment, performance and monitoring',prompt:'Read-only source audit for '+root+': stack/configuration validation, safe defaults, startup/shutdown, HTTPS/proxy, PostgreSQL/Redis connections and timeouts, performance/scaling, health/metrics/logging, dependency lockfiles/audit, migrations, CI/container/deployment artifacts and release gate. Cite exact path:line. Do not inspect payment/M-Pesa implementation or .env secret values. No execution, tests, network, or writes. Distinguish confirmed repo gaps from owner-observed deployment blockers. Return shared schema id production-ops.'}
];
const results=await parallel('Six independent Chama audit areas',()=>areas.map(a=>agent(a.prompt,{brief:a.brief,schema:schema,sandbox:'shared',effort_level:'standard'})),{schema:schema});
const packed=results.map((r,i)=>r.ok?{area:areas[i].id,result:r.value}:{area:areas[i].id,error:{code:r.error.code,message:r.error.message}});
const reducer=await agent('Synthesize the six independent read-only source audit results for Chama 1.0. Preserve exact evidence and separate confirmed source design gaps from suspected issues and deployment validation blockers. Do not add claims unsupported by the returned area results. Explicitly exclude payment/M-Pesa. No source edits or further execution. Return the shared schema with id synthesis. Inputs: '+JSON.stringify(packed),{brief:'Synthesize audit findings and blockers',schema:schema,sandbox:'shared',effort_level:'standard'});
return {areas:packed,synthesis:reducer.ok?reducer.value:{error:{code:reducer.error.code,message:reducer.error.message}},limitations:['This was source-only; no project code/tests were executed because the required isolated OS sandbox is unavailable.','The user requested read-only mode, so no audit artifacts were written.','Payment and M-Pesa implementation were explicitly excluded.']};

